import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.BXmxXpv-.js";const h=JSON.parse('{"title":"Contact us","description":"Contact the Intelligent Computing Systems Laboratory at UESTC for student applications, research collaboration and general inquiries.","frontmatter":{"title":"Contact us","description":"Contact the Intelligent Computing Systems Laboratory at UESTC for student applications, research collaboration and general inquiries.","outline":false,"aside":false},"headers":[],"relativePath":"contact.md","filePath":"en/contact.md","lastUpdated":1783582817000}'),s={name:"contact.md"};function i(n,e,c,l,p,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="contact-us" tabindex="-1">Contact us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact us&quot;">​</a></h1><h2 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h2><p>For general inquiries, please contact <a href="mailto:public@nise.ac.cn" target="_blank" rel="noreferrer">public@nise.ac.cn</a>.</p><p>To reach a specific member, please refer to the <a href="/people">People page</a>.</p><h2 id="prospective-students" tabindex="-1">Prospective Students <a class="header-anchor" href="#prospective-students" aria-label="Permalink to &quot;Prospective Students&quot;">​</a></h2><p>The laboratory welcomes prospective master&#39;s and doctoral students interested in intelligent computing systems, IoT, wireless embedded systems, edge intelligence, and system security.</p><p>Prospective applicants may contact us through the public email address or refer to the <a href="/people#supervisors">supervisors section on the People page</a> to reach a relevant supervisor. Please briefly describe your research interests and include a CV, transcript, and representative project, publication, or code links when applicable.</p><h2 id="collaboration" tabindex="-1">Collaboration <a class="header-anchor" href="#collaboration" aria-label="Permalink to &quot;Collaboration&quot;">​</a></h2><p>We welcome inquiries from universities, research institutes, and industry partners on research collaboration, joint projects, student co-supervision, and system prototype validation. Please contact us through the public email address with a brief description of the background, target direction, and expected format.</p><h2 id="address" tabindex="-1">Address <a class="header-anchor" href="#address" aria-label="Permalink to &quot;Address&quot;">​</a></h2><p>No. 4 Research Building, Qingshuihe Campus, UESTC, West Hi-Tech Zone, Chengdu, Sichuan, China.</p><p>Please make an appointment by email before visiting.</p>',12)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
